import {locationDetails,LOCATION_NOTICE} from './business-profile.mjs';
import {mountCustomerNotice} from './customer-notifications.mjs';
import {api,escape as e,statusLabel,dateLabel,trackingUrl,saveBookmark,copyText,watchUpdates} from './system.mjs';
import {money,findPlan} from './catalog.mjs';
import {registeredPlateLabel} from './plates.mjs';
import {readOrders} from './privacy-storage.mjs';
const host=document.getElementById('tracking-content'),live=document.getElementById('live-state');
const params=new URLSearchParams(location.search),id=params.get('id');let token=new URLSearchParams(location.hash.slice(1)).get('t')||'',stop=null;
if(!token&&id){try{token=readOrders(localStorage).find(q=>q.id===id)?.token||'';}catch{}}
function bookmarks(){
 let list=[];try{list=readOrders(localStorage);}catch{}
 live.textContent='Links guardados neste aparelho';
 host.innerHTML='<section class="system-card"><h2>Seus pedidos neste aparelho.</h2><p class="system-muted">Cada pedido tem um link privado. Guarde-o para acompanhar em outro aparelho.</p>'+(list.length?'<div class="system-list order-list">'+list.map(q=>'<a class="system-row" href="'+e(trackingUrl(q.id,q.token))+'"><span><strong>'+e(q.reference)+'</strong><small>Consultar acompanhamento</small></span><span aria-hidden="true">↗</span></a>').join('')+'</div>':'<div class="system-empty"><h2>Seu próximo cuidado começa aqui.</h2><p>Se já enviou um pedido em outro aparelho, abra o link que recebeu. Se perdeu o link, converse com Mateus.</p><a class="button orange" href="../atendimento/">Preparar orçamento ↗</a></div>')+'<div class="system-actions"><button class="button outline" id="forget-orders" type="button">Apagar links deste aparelho</button><a class="button outline" href="https://wa.me/5511959473298">Falar com Mateus ↗</a></div></section>';
 document.getElementById('forget-orders')?.addEventListener('click',()=>{if(confirm('Apagar os links guardados neste aparelho? Os pedidos continuam na Fine Form.')){localStorage.removeItem('ff-orders-v2');bookmarks();}});
}
function render({quote:q,events}){
 const budget=q.budget,ownUrl=trackingUrl(q.id,token),plan=q.selection.mode==='plan'?findPlan(q.selection.plan):null;
 saveBookmark(q.id,token,q.reference);
 const final=q.confirmedTotal!==null&&q.confirmedTotal!==undefined?q.confirmedTotal:budget.total;
 const totalLabel=budget.hasBase?'Total do pedido':'Subtotal dos cuidados escolhidos';
 const schedule=q.scheduledDate||q.preferredDate,time=q.scheduledTime||q.preferredTime;
 host.innerHTML='<div id="customer-notice"></div>'+(q.status==='pending'?'<p class="system-note" data-request-approval>Sua solicitação aguarda a análise e a aceitação de Mateus. Ainda não há confirmação de atendimento.'+'</p>':'')+'<section class="system-card" data-customer-location><h2>Local de atendimento.</h2>'+(q.location?locationDetails(q.location)+'<p class="system-muted">Confirme a data e o horário com Mateus antes de se deslocar.</p>':'<p>'+LOCATION_NOTICE+'</p>')+'</section><div class="system-grid"><section class="system-card"><span class="status-badge status-'+e(q.status)+'">'+e(statusLabel[q.status])+'</span><h2 style="margin-top:22px">'+e(q.reference)+'</h2><p>Olá, '+e(q.name)+'.</p><p>'+(q.message?e(q.message):q.status==='pending'?'Seu pedido chegou à Fine Form. Mateus vai avaliar os cuidados e combinar o atendimento.':q.status==='completed'?'Seu cuidado foi concluído. Obrigado por confiar na Fine Form.':'Seu pedido foi atualizado por Mateus.')+'</p><div class="system-note"><strong>'+e(q.model)+'</strong><br><strong>'+e(registeredPlateLabel(q))+'</strong><br>'+dateLabel(schedule)+(time?' · '+e(time):' · Horário a combinar')+'</div><div class="system-actions"><button class="button outline" id="refresh-order" type="button">Atualizar</button><a class="button orange" href="https://wa.me/5511959473298?text='+encodeURIComponent('Olá, Mateus! Gostaria de falar sobre meu pedido '+q.reference+'.')+'">Falar com Mateus ↗</a></div>'+(q.subscriptionId&&q.kind==='plan'?'<a class="underlined-link" style="margin-top:20px" href="'+e(trackingUrl(q.subscriptionId,token,'assinatura'))+'">Ver meu Fine Form Care ↗</a>':'')+'</section><section class="system-card"><h2>Seu orçamento.</h2><dl class="quote-box" style="margin:0"><div class="system-list">'+budget.items.map(item=>'<div class="system-row"><span>'+e(item.label)+(item.kind==='monthly'?' · mensalidade':item.kind==='credit'?' · incluída no Care':item.kind==='complement'?' · complemento':'')+'</span><strong>'+money(item.price)+'</strong></div>').join('')+'</div>'+(budget.discount?'<div class="system-row quote-credit"><span>Etapas em comum</span><strong>−'+money(budget.discount)+'</strong></div>':'')+'<div class="quote-total"><span>'+(q.confirmedTotal!==null&&q.confirmedTotal!==undefined?'Valor confirmado':totalLabel)+'</span><strong>'+money(final)+'</strong></div>'+(budget.recurring?'<p class="system-muted">Mensalidade: '+money(budget.recurring)+'/mês.'+(budget.additional?' Adicionais desta visita: '+money(budget.additional)+'.':'')+' Sem cobrança automática pelo site.</p>':'')+'</dl>'+(!budget.hasBase&&q.confirmedTotal===null?'<p class="system-muted">O valor completo será definido na avaliação.</p>':'')+(q.kind==='plan'&&!q.subscriptionId?'<p class="system-muted">O Care é ativado por Mateus após confirmar o pagamento. Até lá, este é um pedido de assinatura.</p>':'')+'</section></div><section class="system-card"><h2>O caminho do seu cuidado.</h2><ol class="system-timeline">'+events.map(event=>'<li><strong>'+e(statusLabel[event.status]||event.status)+'</strong><p>'+e(event.message)+'</p><time>'+e(new Date(event.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))+'</time></li>').join('')+'</ol></section><section class="system-card"><h2>Guarde seu link.</h2><p class="system-muted">Ele dá acesso ao seu acompanhamento. Compartilhe apenas com quem deve acompanhar este pedido.</p><a class="tracking-link" href="'+e(ownUrl)+'">'+e(ownUrl)+'</a><div class="system-actions"><button class="button outline" id="save-order-link" type="button">Guardar link neste aparelho por até 90 dias</button><button class="button outline" id="copy-order-link" type="button">Copiar link</button><a class="button outline" href="./">Meus pedidos neste aparelho</a></div></section>';
 mountCustomerNotice(document.getElementById('customer-notice'),q,token).catch(()=>{});
 document.getElementById('save-order-link').addEventListener('click',()=>{const ok=saveBookmark(q.id,token,q.reference,{remember:true});window.ff?.toast(ok?'Link guardado neste aparelho por até 90 dias.':'O navegador não permitiu guardar o link. Copie-o para um lugar seguro.');});
 document.getElementById('refresh-order').addEventListener('click',()=>load().catch(showError));
 document.getElementById('copy-order-link').addEventListener('click',async()=>{try{await copyText(ownUrl);window.ff?.toast('Link copiado.');}catch(error){window.ff?.toast(error.message);}});
}
function showError(error){live.textContent='Não foi possível atualizar';if(error.status===404){stop?.();host.innerHTML='<div class="system-empty"><h2>Esse link não está disponível.</h2><p>Confira o link completo ou converse com Mateus para receber um novo acompanhamento.</p><a class="button orange" href="https://wa.me/5511959473298">Falar com Mateus ↗</a></div>';}else{let box=document.getElementById('tracking-error');if(!box){box=document.createElement('p');box.id='tracking-error';box.className='system-error';box.setAttribute('role','alert');host.prepend(box);}box.textContent=error.message;}}
async function load(){const data=await api('/api/quotes/'+encodeURIComponent(id),{token});render(data);}
if(!id)bookmarks();else if(!token)showError({status:404});else{load().then(()=>{stop=watchUpdates({scope:'quote',id,token,onChange:()=>load().catch(showError),onState:s=>{live.dataset.live=s;live.textContent=s==='live'?'Atualizações ativas':s==='connecting'?'Conectando atualizações…':'Atualização automática • conexão em recuperação';}});}).catch(showError);}
window.addEventListener('ff:saved-data-cleared',()=>{if(!id)bookmarks();});
window.addEventListener('pagehide',event=>{if(!event.persisted)stop?.();});
